chronously via dynamic import only when it's needed, which helps\n37:  * reduce initial bundle size. This is the recommended way to define lifecycles\n38:  * for most modules.\n39:  *\n40:  * @param lazy A function that returns a Promise resolving to a module with the\n41:  *   component as its default export (i.e., a dynamic import).\n42:  * @param options Configuration options for the OpenMRS component decorator.\n43:  * @returns A function that returns a Promise resolving to a single-spa lifecycle object.\n44:  *\n45:  * @example\n46:  * ```ts\n47:  * import { getAsyncLifecycle } from '@openmrs/esm-framework';\n48:  * const options = { featureName: 'my-feature', moduleName: '@openmrs/esm-my-app' };\n49:  * export const root = getAsyncLifecycle(() => import('./root.component'), options);\n50:  * ```\n51:  */\n52: export function getAsyncLifecycle<T>(\n53:   lazy: () => Promise<{ default: ComponentType<T> }>,\n54:   options: ComponentDecoratorOptions,\n55: ) {\n56:   return () => lazy().then(({ default: Component }) => getLifecycle(Component, options));\n57: }\n58: \n59: /**\n60:  * Creates a single-spa lifecycle for a React component that is already loaded.\n61:  * Unlike {@link getAsyncLifecycle}, this wraps a synchronously-available component\n62:  * in a Promise to match the expected lifecycle interface. Use this when the\n63:  * component doesn't need lazy loading.\n64:  *\n65:  * @param Component The React component to create a lifecycle for.\n66:  * @param options Configuration options for the OpenMRS component decorator.\n67:  * @returns A function that returns a Promise resolving to a single-spa lifecycle object.\n68:  *\n69:  * @example\n70:  * ```ts\n71:  * import { getSyncLifecycle } from '@openmrs/esm-framework';\n72:  * import MyComponent from './MyComponent';\n73:  * const options = { featureName: 'my-feature', moduleName: '@openmrs/esm-my-app' };\n74:  * export const myExtension = getSyncLifecycle(MyComponent, options);\n75:  * ```\n76:  */\n77: export function getSyncLifecycle<T>(Component: ComponentType<T>, options: ComponentDecoratorOptions) {\n78:   return () => Promise.resolve(getLifecycle(Component, options));\n79: }\n80: \n81: /**\n82:  * @deprecated Use getAsyncLifecycle instead.\n83:  */\n84: export const getAsyncExtensionLifecycle = getAsyncLifecycle;\n85: \n\n(End of file - 85 lines total)\n</content>"}]}]},"parent_tool_use_id":null,"session_id":"2955d883-5312-46e3-8995-da5d6d809db4","uuid":"357ba43b-b39d-4d22-98e1-2fe0c8b7511f","timestamp":"2026-10-20T03:58:29.066Z","tool_use_result":[{"type":"text","text":"<repo>github.com/openmrs/openmrs-esm-core</repo>\n<path>packages/framework/esm-react-utils/src/getLifecycle.ts</path>\n<url>undefined</url>\n<content>\n1: /** @module @category Framework */\n2: import type { ComponentType } from 'react';\n3: import React from 'react';\n4: import ReactDOMClient from 'react-dom/client';\n5: import type { AppProps } from 'single-spa';\n6: import singleSpaReact, { type ReactAppOrParcel } from 'single-spa-react';\n7: import type { ComponentDecoratorOptions } from './openmrsComponentDecorator';\n8: import { openmrsComponentDecorator } from './openmrsComponentDecorator';\n9: \n10: /**\n11:  * Creates a single-spa lifecycle object for a React component. The component is\n12:  * wrapped with the OpenMRS component decorator which provides standard functionality\n13:  * like error boundaries, configuration, and extension support.\n14:  *\n15:  * @param Component The React component to create a lifecycle for.\n16:  * @param options Configuration options for the OpenMRS component decorator.\n17:  * @returns A single-spa lifecycle object with bootstrap, mount, and unmount functions.\n18:  *\n19:  * @example\n20:  * ```ts\n21:  * import { getLifecycle } from '@openmrs/esm-framework';\n22:  * import MyComponent from './MyComponent';\n23:  * export const lifecycle = getLifecycle(MyComponent, { featureName: 'my-feature', moduleName: '@openmrs/esm-my-app' });\n24:  * ```\n25:  */\